import * as React from "react"
import { PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import SubNavigation from "../components/subnav";
import IndustryGrid from "../components/industryGrid";

const userData: UserProfile = data;

const IndustryPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="Tofu"
      footerLogoFill="fill-Tofu"
      bgColorPage="DeepSea"
      bgImage={images.bgIndustry.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <SubNavigation menuItems={data.submenuIndustry} submenuTitle={t("submenu.industryTitle") || ""}/>
        <section className={styles.container}>
            <section className={styles.section}>
                <div className="flex flex-col w-full sm:w-1/2">
                    <h1 className="head-3 sm:head-1" dangerouslySetInnerHTML={{ __html: t("industry.title") ?? "" }} />
                    <p className="body-2 sm:body-1">{t("industry.paragraph1")}</p>
                    <div className="mt-4 self-start">
                        <a className="inline-block body-4 px-28 sm:px-32 py-4 border-2 rounded-xl border-Tofu hover:bg-Tofu hover:text-DarkSea transition duration-300" href="/contact-us" >
                          {t("industry.cta")}
                        </a>
                    </div>
                </div>
            </section>
            <IndustryGrid />
            <section className={`${styles.section} mt-16`}>
                <div className="flex flex-col w-full sm:w-1/2">
                  <h1 className="head-3 sm:head-1 uppercase" dangerouslySetInnerHTML={{ __html: t("industry.botomTitle") ?? "" }} />
                  <p className="body-2 sm:body-1">{t("industry.botomText")}</p>
                  <div className="mt-4 self-start">
                      <a className="inline-block body-4 px-28 sm:px-32 py-4 border-2 rounded-xl border-Tofu hover:bg-Tofu hover:text-DarkSea transition duration-300" href="/contact-us" >
                        {t("industry.cta")}
                      </a>
                  </div>
                </div>
            </section>
        </section>
    </Layout>
  )
}

export default IndustryPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16 text-Tofu mt-[300px] sm:mt-[422px] mb-48 sm:mb-96",
  section: "flex flex-col sm:flex-row items-center gap-8 mb-20",
}